using Microsoft.EntityFrameworkCore;

namespace SportsCourtBooking.Infrastructure.Data;

public static class VoucherSchemaExtensions
{
    private const string VoucherSchemaSql = """
        CREATE TABLE IF NOT EXISTS "Vouchers" (
            "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "OwnerId" integer NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
            "Code" character varying(30) NOT NULL,
            "DiscountType" integer NOT NULL,
            "DiscountValue" numeric(18,2) NOT NULL,
            "StartDate" date NOT NULL,
            "EndDate" date NOT NULL,
            "UsageLimit" integer NULL,
            "IsActive" boolean NOT NULL DEFAULT TRUE,
            "CreatedAt" timestamp with time zone NOT NULL,
            "UpdatedAt" timestamp with time zone NULL
        );

        CREATE UNIQUE INDEX IF NOT EXISTS "IX_Vouchers_OwnerId_Code"
            ON "Vouchers" ("OwnerId", "Code");

        DO $$
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM pg_constraint
                WHERE conname = 'ck_vouchers_values'
                  AND conrelid = '"Vouchers"'::regclass
            ) THEN
                ALTER TABLE "Vouchers"
                    ADD CONSTRAINT ck_vouchers_values
                    CHECK (("DiscountType" = 1 AND "DiscountValue" > 0 AND "DiscountValue" <= 100)
                        OR ("DiscountType" = 2 AND "DiscountValue" > 0));
            END IF;

            IF NOT EXISTS (
                SELECT 1
                FROM pg_constraint
                WHERE conname = 'ck_vouchers_dates_and_usage'
                  AND conrelid = '"Vouchers"'::regclass
            ) THEN
                ALTER TABLE "Vouchers"
                    ADD CONSTRAINT ck_vouchers_dates_and_usage
                    CHECK ("EndDate" >= "StartDate" AND ("UsageLimit" IS NULL OR "UsageLimit" > 0));
            END IF;
        END $$;

        ALTER TABLE "Bookings"
            ADD COLUMN IF NOT EXISTS "VoucherId" integer NULL;

        ALTER TABLE "Bookings"
            ADD COLUMN IF NOT EXISTS "VoucherCode" character varying(30) NULL;

        ALTER TABLE "Bookings"
            ADD COLUMN IF NOT EXISTS "DiscountAmount" numeric(18,2) NOT NULL DEFAULT 0;

        DO $$
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM pg_constraint
                WHERE conname = 'FK_Bookings_Vouchers_VoucherId'
                  AND conrelid = '"Bookings"'::regclass
            ) THEN
                ALTER TABLE "Bookings"
                    ADD CONSTRAINT "FK_Bookings_Vouchers_VoucherId"
                    FOREIGN KEY ("VoucherId") REFERENCES "Vouchers" ("Id") ON DELETE RESTRICT;
            END IF;

            IF NOT EXISTS (
                SELECT 1
                FROM pg_constraint
                WHERE conname = 'ck_bookings_voucher_discount'
                  AND conrelid = '"Bookings"'::regclass
            ) THEN
                ALTER TABLE "Bookings"
                    ADD CONSTRAINT ck_bookings_voucher_discount
                    CHECK ("DiscountAmount" >= 0 AND
                        (("VoucherId" IS NULL AND "VoucherCode" IS NULL AND "DiscountAmount" = 0)
                        OR ("VoucherId" IS NOT NULL AND "VoucherCode" IS NOT NULL)));
            END IF;
        END $$;

        CREATE INDEX IF NOT EXISTS "IX_Bookings_VoucherId" ON "Bookings" ("VoucherId");
        """;

    public static Task EnsureVoucherSchemaAsync(
        this AppDbContext db,
        CancellationToken cancellationToken = default)
    {
        if (!db.Database.IsNpgsql())
        {
            throw new InvalidOperationException("Voucher schema requires PostgreSQL.");
        }

        return db.Database.ExecuteSqlRawAsync(VoucherSchemaSql, cancellationToken);
    }
}
